import os, sys, json
import pytest
import control.nlsys as nlsys

REPO_ROOT = '/testbed'
TEST_FILE = '/testbed/qa_instances_eval/python-control/nlsys_interconnect_call_coverage_suite/files/tests/qa/nlsys_interconnect_call_coverage_suite_test.py'
PREFIXES = (
    'control.nlsys.',
    'control.iosys.',
    'control.statesp.',
    'control.xferfcn.',
    'control.bdalg.',
)

active_depth = 0
covered = set()


def relpath_if_possible(path):
    ap = os.path.abspath(path)
    rr = os.path.abspath(REPO_ROOT)
    if ap.startswith(rr + os.sep):
        return os.path.relpath(ap, rr).replace('\\\\', '/')
    return ap.replace('\\\\', '/')


def profiler(frame, event, arg):
    global active_depth
    if event not in ('call', 'return'):
        return profiler

    module = frame.f_globals.get('__name__', '')
    co_name = frame.f_code.co_name
    filename = frame.f_code.co_filename

    is_interconnect = (
        module == 'control.nlsys' and
        co_name == 'interconnect' and
        filename.replace('\\\\', '/').endswith('/control/nlsys.py')
    )

    if event == 'call':
        if is_interconnect:
            active_depth += 1

        if active_depth > 0:
            if '<' not in co_name and '>' not in co_name:
                func = f"{module}.{co_name}"
                if func.startswith(PREFIXES):
                    relf = relpath_if_possible(filename)
                    if not relf.startswith('control/tests'):
                        covered.add((relf, func))

    elif event == 'return':
        if is_interconnect:
            active_depth -= 1
            if active_depth < 0:
                active_depth = 0

    return profiler

sys.setprofile(profiler)
exit_code = pytest.main([TEST_FILE, '-q'])
sys.setprofile(None)

if exit_code != 0:
    raise SystemExit(exit_code)

covered_list = [
    {'file': f, 'func': fn}
    for f, fn in sorted(covered, key=lambda x: (x[0], x[1]))
]
print(json.dumps(covered_list, indent=2))
print(f"COUNT={len(covered_list)}")
